output-exprs.el:
idOrigen:if(
  a!isNotNullOrEmpty(
    index(
      pv!archivo,
      "origen",
      "identificador",
      null
    )
  ),
  /*and(*/
  /*pv!archivo <> null,*/
  /*pv!archivo.origen <> null,*/
  /*pv!archivo.origen.identificador <> null,*/
  /*),*/
  index(
    pv!archivo,
    "origen",
    "identificador",
    null
  ),
  pv!idOrigen
)

infoFolioProceso:'type!{urn:com:appian:types:PIMF}PIMF_FOLIO_PROCESO_BO'( folio: pv!folio, proceso: 'type!{urn:com:appian:types:PIMF}PIMF_CATALOGO_OB'( id: index( pv!datoSeleccionado_map, "operationalProcessInfo", "process", "processId", null ), descripcion: index( pv!datoSeleccionado_map, "operationalProcessInfo", "process", "processDescription", null ), tipoCatalogo: 2/*ID TIPO CATALOGO PARA PROCESO*/
), subproceso: 'type!{urn:com:appian:types:PIMF}PIMF_CATALOGO_OB'( id: index( pv!datoSeleccionado_map, "operationalProcessInfo", "subprocess", "subprocessId", null ), descripcion: index( pv!datoSeleccionado_map, "operationalProcessInfo", "subprocess", "subprocessDescription", null ), tipoCatalogo: 3/*ID TIPO CATALOGO PARA subPROCESO*/
), fechaActualizacion: index( pv!datoSeleccionado_map, "auditInfo", "updateDate", null ), usuarioCreacion: if(a!isNotNullOrEmpty(pv!user),pv!user,index( pv!datoSeleccionado_map, "auditInfo", "creationUser", null )), usuarioActualizacion: if(a!isNotNullOrEmpty(pv!user),pv!user,index( pv!datoSeleccionado_map, "auditInfo", "updateUser", null )) )
